<?php
require __DIR__.'/bootstrap.php';
site_header($pdo,'Home');
$cats=$pdo->query('SELECT * FROM categories WHERE active=1 ORDER BY name LIMIT 4')->fetchAll();
$products=$pdo->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1 ORDER BY p.created_at DESC LIMIT 8')->fetchAll();
$hero=setting($pdo,'hero_image',''); ?>
<section class="hero" style="background-image:linear-gradient(90deg,rgba(17,17,17,.55),rgba(17,17,17,.08)),url('<?=e($hero?:'https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=2000&q=85')?>')"><div class="hero-copy"><span class="eyebrow">A CONSIDERED COLLECTION</span><h1><?=e(setting($pdo,'hero_heading','THE ART OF EVERYDAY LIVING'))?></h1><p><?=e(setting($pdo,'hero_description','Discover a carefully curated collection designed for modern lifestyles.'))?></p><a class="button button-light" href="<?=e(setting($pdo,'hero_link','shop.php'))?>"><?=e(setting($pdo,'hero_cta','EXPLORE COLLECTION'))?></a></div></section>
<section class="section"><div class="section-heading"><div><span class="eyebrow">DISCOVER</span><h2>Shop by category</h2></div><a class="text-link" href="shop.php">VIEW ALL ↗</a></div><div class="category-grid"><?php foreach($cats as $c): ?><a class="category-card" href="shop.php?category=<?=(int)$c['id']?>"><img src="<?=e($c['image']?:'assets/images/placeholder.svg')?>" alt="<?=e($c['name'])?>" loading="lazy"><span><?=e($c['name'])?></span></a><?php endforeach; ?><?php if(!$cats): ?><p>Collections are being curated. Visit the shop soon.</p><?php endif; ?></div></section>
<section class="section section-ivory"><div class="section-heading"><div><span class="eyebrow">THE LATEST EDIT</span><h2>New arrivals</h2></div><a class="text-link" href="shop.php?sort=newest">DISCOVER ALL ↗</a></div><div class="product-grid"><?php foreach($products as $p): ?><article class="product-card"><a href="product.php?slug=<?=e($p['slug'])?>"><div class="product-image"><img src="<?=e(product_image($p['image']))?>" alt="<?=e($p['name'])?>" loading="lazy"><?php if($p['sale_price'] && $p['sale_price']<$p['price']): ?><span class="badge">SALE</span><?php endif; ?></div><div class="product-meta"><span><?=e($p['category_name']??'Collection')?></span><h3><?=e($p['name'])?></h3><b><?=money((float)($p['sale_price']?:$p['price']))?></b></div></a></article><?php endforeach; ?></div></section>
<section class="story-band"><span class="eyebrow">OUR PHILOSOPHY</span><h2>Less, but considered.</h2><p><?=e(setting($pdo,'about_text','A thoughtful edit of enduring essentials, selected with care for the way you live.'))?></p><a class="text-link" href="about.php">DISCOVER OUR STORY ↗</a></section>
<?php site_footer($pdo); ?>
